\newcommand{\RBShape}{\mathrm{RBShape}}

\title{Characterizing Finite Posets Whose Probabilistic Powerdomain
Is an RB-Domain: The Independence of the Two Defining Conditions}

\author{Aristotle}

\date{\today}

\begin{document}

\begin{abstract}
The probabilistic powerdomain---the construction that replaces a space of states
by the space of probability distributions over it---is notoriously ill-behaved
with respect to the class of \emph{RB-domains} (retracts of bifinite domains),
the robust, closure-friendly class most prized in denotational semantics. For
finite partially ordered sets, a folklore characterization asserts that the
probabilistic powerdomain returns an RB-domain precisely when the poset has a
\emph{least element} and its undirected \emph{Hasse graph is a tree} (connected
and acyclic). We call such a poset \emph{RB-shaped}. We isolate the combinatorial
core of this characterization and prove that its two conditions are logically
\emph{independent}: neither implies the other, and neither alone suffices. Our
central reusable lemma is a \emph{diamond obstruction}: any poset containing a
covering diamond $a \covby b$, $a \covby c$, $b \covby d$, $c \covby d$ with
$b \ne c$ has a non-acyclic Hasse graph, hence is not RB-shaped. We refute the
conjecture that a least element alone forces RB-shape via the four-element Boolean
lattice (the diamond); we refute the conjecture that acyclicity alone forces a
least element via the two-element antichain, strengthened from ``forest'' to
``genuine tree'' by the three-element ``V'' poset. A non-vacuity check---the
two-element chain, which is RB-shaped---completes the picture.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
Denotational semantics models programs as elements of structured spaces called
\emph{domains} and program constructs as continuous maps between them. To account
for \emph{randomized} programs one enriches this picture with a
\emph{probabilistic powerdomain}: a functor sending a domain $D$ to a domain
$V(D)$ whose points are continuous valuations, the domain-theoretic surrogate for
probability measures on $D$. For such a semantics to compose well one wants $V$
to preserve the class one works in. The most desirable such class is that of
\emph{RB-domains}, equivalently the retracts of bifinite (SFP) domains: cartesian
closed, closed under many constructions, and technically robust. The central
long-standing difficulty, documented in Jung and Tix's study \emph{The
troublesome probabilistic powerdomain} (1998), is that $V$ does \emph{not}
preserve this class in general.

\subsection{The finite case as a combinatorial testbed}
For a finite poset $P$ the situation collapses into pure combinatorics. The
folklore characterization reads: the probabilistic powerdomain of a finite poset
$P$ is an RB-domain if and only if $P$ has a least element and the undirected
Hasse graph of $P$ is a tree. We do not reconstruct this analytic equivalence;
instead we study its combinatorial shadow, the two-conjunct predicate we call
\emph{RB-shape}, and answer the structural question any biconditional provokes:
\emph{are both conditions truly necessary?}

\subsection{Contributions}
\begin{enumerate}
\item A reusable diamond obstruction (\S\ref{sec:diamond}): any poset containing a
covering diamond has a non-acyclic Hasse graph.
\item Refutation of ``least element $\Rightarrow$ RB-shape'' (\S\ref{sec:conjA})
via the four-element Boolean lattice.
\item Refutation of ``acyclic Hasse graph $\Rightarrow$ least element''
(\S\ref{sec:conjB}) via the two-element antichain.
\item Strengthening from forest to tree (\S\ref{sec:tree}) via the ``V'' poset.
\item A non-vacuity check (\S\ref{sec:chain}): the two-element chain is RB-shaped.
\end{enumerate}

\section{Preliminaries on Orders and Their Diagrams}

Throughout, $P$ denotes a partially ordered set with order $\le$, and $x < y$
abbreviates $x \le y \wedge x \ne y$.

\begin{definition}[Covering relation]
For $x, y \in P$ we say $y$ \emph{covers} $x$, written $x \covby y$, if $x < y$
and there is no $z$ with $x < z < y$.
\end{definition}

\begin{definition}[Hasse graph]
The \emph{Hasse graph} of $P$, denoted $\Hasse(P)$, is the undirected simple
graph on vertex set $P$ in which distinct $a, b$ are adjacent iff one covers the
other:
\[
a \sim_{\Hasse(P)} b \iff (a \covby b) \vee (b \covby a).
\]
This relation is symmetric and loop-free.
\end{definition}

\begin{definition}[Least element]
$P$ \emph{has a least element} if there exists $\bot \in P$ with $\bot \le x$ for
all $x$. When it exists $\bot$ is unique by antisymmetry.
\end{definition}

A \emph{path} is a walk with no repeated vertex; a graph is \emph{connected} if
every pair of vertices is joined by a walk, \emph{acyclic} if between any two
vertices there is at most one path, a \emph{forest} if acyclic, and a \emph{tree}
if connected and acyclic.

\begin{definition}[RB-shape]
A finite poset $P$ is \emph{RB-shaped} if it has a least element and $\Hasse(P)$
is a tree:
\[
\RBShape(P) :\iff (P \text{ has a least element}) \wedge (\Hasse(P)\text{ is a tree}).
\]
\end{definition}

\section{The Guiding Conjectures}

\begin{conjecture}\label{conj:A}
Every finite poset with a least element is RB-shaped.
\end{conjecture}

\begin{conjecture}\label{conj:B}
Every finite poset whose Hasse graph is acyclic has a least element.
\end{conjecture}

We refute Conjecture~\ref{conj:A} in \S\ref{sec:conjA} and
Conjecture~\ref{conj:B} in \S\ref{sec:conjB}, then sharpen the latter in
\S\ref{sec:tree}.

\section{The Diamond Obstruction}\label{sec:diamond}

\begin{definition}[Covering diamond]
A poset $P$ contains a \emph{covering diamond} if there are $a, b, c, d \in P$
with
\[
a \covby b,\quad a \covby c,\quad b \covby d,\quad c \covby d,\quad b \ne c.
\]
\end{definition}

\begin{theorem}[Diamond destroys acyclicity]\label{thm:diamond}
If a poset $P$ contains a covering diamond $a \covby b$, $a \covby c$,
$b \covby d$, $c \covby d$ with $b \ne c$, then $\Hasse(P)$ is not acyclic.
\end{theorem}

\begin{proof}
The covers $a \covby b$ and $b \covby d$ give edges $a \sim b$ and $b \sim d$, so
$p_1 : a - b - d$ is a walk from $a$ to $d$. Its vertices are pairwise distinct:
$a \ne b$ and $b \ne d$ since covering implies strict inequality, and $a \ne d$
since $a < b < d$. Hence $p_1$ is a path. Symmetrically $p_2 : a - c - d$ is a
path from $a$ to $d$. The two paths share endpoints $a, d$ but differ, since the
interior vertex of $p_1$ is $b$ and that of $p_2$ is $c$, with $b \ne c$. Two
distinct paths with equal endpoints contradict acyclicity. Therefore
$\Hasse(P)$ is not acyclic.
\end{proof}

\begin{corollary}[Diamond destroys treeness]\label{cor:tree}
Under the hypotheses of Theorem~\ref{thm:diamond}, $\Hasse(P)$ is not a tree.
\end{corollary}

\begin{proof}
A tree is acyclic; apply Theorem~\ref{thm:diamond}.
\end{proof}

\begin{corollary}[Diamond destroys RB-shape]\label{cor:rb}
Under the hypotheses of Theorem~\ref{thm:diamond}, $P$ is not RB-shaped.
\end{corollary}

\begin{proof}
RB-shape requires $\Hasse(P)$ to be a tree, which Corollary~\ref{cor:tree}
forbids.
\end{proof}

\section{Refuting Conjecture A: A Least Element Is Not Enough}\label{sec:conjA}

Let $\mathbf{2}\times\mathbf{2}$ be the four-element Boolean lattice $\{0,1\}^2$
ordered coordinatewise, with $(1,0)$ and $(0,1)$ incomparable---the
\emph{diamond}.

\begin{proposition}\label{prop:diamond-least}
$\mathbf{2}\times\mathbf{2}$ has a least element.
\end{proposition}

\begin{proof}
$(0,0) \le (x,y)$ for all $(x,y)$ since $0 \le x$ and $0 \le y$.
\end{proof}

\begin{proposition}\label{prop:diamond-notrb}
$\mathbf{2}\times\mathbf{2}$ is not RB-shaped.
\end{proposition}

\begin{proof}
The covers $(0,0)\covby(1,0)$, $(0,0)\covby(0,1)$, $(1,0)\covby(1,1)$,
$(0,1)\covby(1,1)$ hold with $(1,0)\ne(0,1)$, so there is a covering diamond. By
Corollary~\ref{cor:rb} the poset is not RB-shaped.
\end{proof}

\begin{theorem}[Refutation of Conjecture~\ref{conj:A}]
Having a least element is not sufficient for RB-shape:
$\mathbf{2}\times\mathbf{2}$ has a least element yet is not RB-shaped.
\end{theorem}

\begin{proof}
Combine Propositions~\ref{prop:diamond-least} and~\ref{prop:diamond-notrb}.
\end{proof}

This is the classical Jung--Tix diamond obstruction in combinatorial form: the
configuration that makes the powerdomain misbehave is exactly the four-cycle that
keeps the Hasse graph from being a tree.

\section{Refuting Conjecture B: Acyclicity Is Not Enough}\label{sec:conjB}

Let $A_2$ be the two-element \emph{antichain}: the set $\{a, b\}$ with $x \le y$
iff $x = y$.

\begin{proposition}\label{prop:anti-acyclic}
$\Hasse(A_2)$ is edgeless, hence acyclic.
\end{proposition}

\begin{proof}
If $x < y$ then $x \le y$ and $x \ne y$; but $x \le y$ forces $x = y$, a
contradiction. So no strict inequality holds, no cover holds, and $\Hasse(A_2)$
has no edges; an edgeless graph is acyclic.
\end{proof}

\begin{proposition}\label{prop:anti-noleast}
$A_2$ has no least element.
\end{proposition}

\begin{proof}
A least $w$ would satisfy $w \le a$ and $w \le b$, i.e. $w = a$ and $w = b$,
forcing $a = b$, a contradiction.
\end{proof}

\begin{theorem}[Refutation of Conjecture~\ref{conj:B}]
An acyclic Hasse graph does not force a least element: $A_2$ has an acyclic Hasse
graph yet no least element.
\end{theorem}

\begin{proof}
Combine Propositions~\ref{prop:anti-acyclic} and~\ref{prop:anti-noleast}.
\end{proof}

\section{A Genuine Tree Without a Least Element}\label{sec:tree}

The antichain is disconnected. We close the loophole that a \emph{connected} tree
might force a least element. Let $V_3$ be the ``V'' poset on $\{a, b, c\}$ with
\[
x \le y \iff x = y \ \vee\ y = c,
\]
so $a < c$, $b < c$, and $a, b$ incomparable.

\begin{proposition}\label{prop:v-tree}
The covers of $V_3$ are exactly $a \covby c$ and $b \covby c$, so $\Hasse(V_3)$ is
the path $a - c - b$, a genuine tree (connected and acyclic).
\end{proposition}

\begin{proof}
$a < c$ with nothing strictly between gives $a \covby c$; symmetrically
$b \covby c$; there are no other strict inequalities. The edges $a \sim c$ and
$b \sim c$ form a two-edge path. It is connected (all vertices reach $c$) and
acyclic (three vertices, two edges, no cycle; each edge is a bridge).
\end{proof}

\begin{proposition}\label{prop:v-noleast}
$V_3$ has no least element.
\end{proposition}

\begin{proof}
A least $w$ would satisfy $w \le a$ and $w \le b$, forcing $w = a$ and $w = b$,
hence $a = b$, a contradiction. Thus $a$ and $b$ are both minimal.
\end{proof}

\begin{theorem}[Strengthened refutation of Conjecture~\ref{conj:B}]
Even a genuine tree Hasse graph does not force a least element: $V_3$ has a tree
Hasse graph yet no least element.
\end{theorem}

\begin{proof}
Combine Propositions~\ref{prop:v-tree} and~\ref{prop:v-noleast}.
\end{proof}

\section{Non-Vacuity: The Chain Is RB-Shaped}\label{sec:chain}

Let $\mathbf{2}$ be the two-element chain $\{0,1\}$ with $0 < 1$.

\begin{proposition}\label{prop:chain-least}
$\mathbf{2}$ has least element $0$.
\end{proposition}

\begin{proof}
$0 \le 0$ and $0 \le 1$.
\end{proof}

\begin{proposition}\label{prop:chain-tree}
$\Hasse(\mathbf{2})$ is a tree.
\end{proposition}

\begin{proof}
The single cover $0 \covby 1$ gives one edge; a single edge on two vertices is
connected and acyclic, hence a tree.
\end{proof}

\begin{theorem}
$\mathbf{2}$ is RB-shaped.
\end{theorem}

\begin{proof}
Combine Propositions~\ref{prop:chain-least} and~\ref{prop:chain-tree}.
\end{proof}

\section{Discussion}

\subsection{The independence picture}
The four posets populate a table indexed by the two conjuncts of RB-shape:

\begin{center}
\begin{tabular}{lccc}
\toprule
Poset & Least element? & Tree? & RB-shaped? \\
\midrule
Chain $\mathbf{2}$ & yes & yes & yes \\
Diamond $\mathbf{2}\times\mathbf{2}$ & yes & no (4-cycle) & no \\
``V'' poset $V_3$ & no & yes (path) & no \\
Antichain $A_2$ & no & yes (forest) & no \\
\bottomrule
\end{tabular}
\end{center}

The diamond (yes, no) and the ``V'' (no, yes) prove logical independence; the
chain (yes, yes) proves satisfiability; the $(\text{no},\text{no})$ cell is
realized by, e.g., a disjoint union of two diamonds.

\subsection{Minimality}
A cycle in a Hasse graph needs at least four vertices, so the diamond is the
smallest poset with a least element and a non-tree Hasse graph. The ``V'' is the
smallest connected poset with a tree Hasse graph and no least element.

\subsection{Relation to the powerdomain problem}
The diamond obstruction is the combinatorial fingerprint of the analytic
phenomenon that makes the probabilistic powerdomain troublesome: where two
incomparable elements share a common lower and upper cover, valuations acquire an
extra degree of freedom the RB-domain class fails to absorb.

\subsection{Scope}
We prove the structure of the predicate RB-shape---the diamond obstruction, the
independence of the two conjuncts, and non-vacuity---rather than the full analytic
equivalence, which involves valuations, bifinite retracts, and the powerdomain
functor.

\section{Future Directions}

\begin{itemize}
\item \emph{Connected tree without a least element}---resolved here by the ``V''
poset.
\item \emph{Multi-element chains and joins}: catalogue which tree-shaped posets
with a least element arise, completing the positive side.
\item \emph{From shadow to substance}: formalize valuations, the powerdomain
functor, and bifinite retracts, and connect them to the combinatorial predicate.
\item \emph{Higher obstructions}: identify minimal forbidden configurations for
non-tree Hasse graphs and any analogous theory on infinite domains.
\end{itemize}

\section{Conclusion}
A single reusable lemma---the diamond obstruction---shows that any covering
diamond destroys RB-shape. From it we refuted that a least element suffices (the
diamond), refuted that acyclicity suffices (the antichain), strengthened the
latter to genuine trees (the ``V''), and confirmed non-vacuity (the chain). The
two defining conditions are independent, and the diamond and the ``V'' are the
minimal witnesses of the two distinct failure modes.

\end{document}

