    for s in elements:
        if s in seen:
            continue
        comps += 1
        stack = [s]
        seen.add(s)
        while stack:
            u = stack.pop()
            for v in adj[u]:
                if v not in seen:
                    seen.add(v)
                    stack.append(v)
    n = len(elements)
    e = len(covers)
    connected = comps == 1
    acyclic = e == n - comps
    return connected and acyclic

